"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["21311"],{37589(e){e.exports=JSON.parse('{"id":"F512","slug":"circular-interest-sweep","name":"Interest on Average Debt with a Cash Sweep (Circularity Solved)","subject":"Accounting Mastery & Financial Modeling","section":"Modeling craft","topic":"Modeling craft","level":"Intermediate","aliases":["circular reference","average balance interest","cash sweep","debt schedule"],"formula":{"latex":"B_{1}=\\\\frac{B_{0}\\\\left(1+\\\\tfrac{(1-t)r}{2}\\\\right)-F}{1-\\\\tfrac{(1-t)r}{2}},\\\\quad \\\\text{Interest}=r\\\\,\\\\frac{B_{0}+B_{1}}{2}","also":[],"text":"Closing debt B1 = [Opening debt x (1 + (1 - t) x r / 2) - Cash available F] / [1 - (1 - t) x r / 2]; Interest = Rate x (Opening + Closing) / 2"},"symbols":[{"symbol":"B_0, B_1","meaning":"Opening and closing debt","unit":"money"},{"symbol":"r","meaning":"Interest rate on the debt","unit":"per year"},{"symbol":"t","meaning":"Tax rate","unit":"percent"},{"symbol":"F","meaning":"Cash flow available for debt repayment before interest, after the tax on operations","unit":"money"}],"when_to_use":"Use it to avoid a circular reference in a model. Interest on the average balance depends on closing debt, which depends on the cash left after interest, which depends on interest. Solving the loop algebraically gives the answer in one step, with no iteration or macro, and no risk of the model breaking.","worked_example":{"problem":"Opening debt is 600 at 6% interest. The tax rate is 25%. Cash flow before interest available for repayment, after tax on operations, is 150, all of which is swept to debt.","inputs":{"b0":600,"r":6,"t":25,"f":150},"steps":[{"label":"k = (1 - t) x r / 2","working":"(1-0.25) x 0.06 / 2","value":"0.02250"},{"label":"Closing debt B1 = (B0 x (1 + k) - F) / (1 - k)","working":"(600 x (1+0.0225)-150) / (1-0.0225)","value":"474.17"},{"label":"Interest = r x (B0 + B1) / 2","working":"0.06 x (600+474.169) / 2","value":"32.23"},{"label":"Repayment = B0 - B1","working":"600-474.169","value":"125.83"},{"label":"Check: F - interest x (1 - t)","working":"150-32.2251 x (1-0.25)","value":"125.83"}],"answer":"Closing debt is 474.17. Interest on the average balance is 32.23, and repayment is 125.83. Check: cash available less after-tax interest is 125.83, the same as the repayment."},"calculator":{"available":true,"inputs":[{"id":"b0","label":"Opening debt","unit":"money","type":"number","default":600,"hint":""},{"id":"r","label":"Interest rate","unit":"%","type":"number","default":6,"hint":""},{"id":"t","label":"Tax rate","unit":"%","type":"number","default":25,"hint":""},{"id":"f","label":"Cash available before interest (after operating tax)","unit":"money","type":"number","default":150,"hint":""}],"checks":[{"expr":"b0>0 and r>=0 and f>=0","message":"Opening debt must be above zero, and the rate and cash not negative."}],"steps":[{"id":"k","label":"k = (1 - t) x r / 2","expr":"(1-t)*r/2","format":"num5"},{"id":"b1","label":"Closing debt B1 = (B0 x (1 + k) - F) / (1 - k)","expr":"(b0*(1+k)-f)/(1-k)","format":"money"},{"id":"interest","label":"Interest = r x (B0 + B1) / 2","expr":"r*(b0+b1)/2","format":"money"},{"id":"repay","label":"Repayment = B0 - B1","expr":"b0-b1","format":"money"},{"id":"check","label":"Check: F - interest x (1 - t)","expr":"f-interest*(1-t)","format":"money"}],"results":["b1","interest","repay"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"k":0.0225,"b1":474.1687979539642,"interest":32.22506393861892,"repay":125.8312020460358,"check":125.8312020460358}},"finder":{"finds":"Closing debt and interest with no circular reference","needs":"Opening debt, rate, tax rate, cash available"},"related":[{"slug":"loan-balance","name":"Remaining Loan Balance"},{"slug":"loan-interest-split","name":"Interest and Principal in a Loan Payment"},{"slug":"lbo-returns","name":"LBO Returns (MOIC and IRR)"}],"related_ids":["F033","F030","F201"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>B</mi><mn>1</mn></msub><mo>=</mo><mfrac><mrow><msub><mi>B</mi><mn>0</mn></msub><mrow><mo fence=\\"true\\">(</mo><mn>1</mn><mo>+</mo><mstyle displaystyle=\\"false\\" scriptlevel=\\"0\\"><mfrac><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>t</mi><mo stretchy=\\"false\\">)</mo><mi>r</mi></mrow><mn>2</mn></mfrac></mstyle><mo fence=\\"true\\">)</mo></mrow><mo>\u2212</mo><mi>F</mi></mrow><mrow><mn>1</mn><mo>\u2212</mo><mstyle displaystyle=\\"false\\" scriptlevel=\\"0\\"><mfrac><mrow><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>t</mi><mo stretchy=\\"false\\">)</mo><mi>r</mi></mrow><mn>2</mn></mfrac></mstyle></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Interest</mtext><mo>=</mo><mi>r</mi><mtext>\u2009</mtext><mfrac><mrow><msub><mi>B</mi><mn>0</mn></msub><mo>+</mo><msub><mi>B</mi><mn>1</mn></msub></mrow><mn>2</mn></mfrac></mrow><annotation encoding=\\"application/x-tex\\">B_{1}=\\\\frac{B_{0}\\\\left(1+\\\\tfrac{(1-t)r}{2}\\\\right)-F}{1-\\\\tfrac{(1-t)r}{2}},\\\\quad \\\\text{Interest}=r\\\\,\\\\frac{B_{0}+B_{1}}{2}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"interest-coverage","name":"Interest Coverage Ratio"},"next":{"slug":"interest-rate-build-up","name":"Interest Rate Build-Up"},"lesson":null,"total":522}')}}]);